import unittest
import mock
from mock import patch, call
from taf.ul.oam.selenium_coam.pages.alarms import AlarmsCommonAction, ActiveAlarmsPage, \
    ActiveAlarmsPageViewPanel, AlarmHistoryPage, AlarmHistoryPageViewPanel, \
    FaultTogglingHistory, FaultTogglingHistoryViewPanel


class TestAlarmsCommonAction(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.alarms_common_action = AlarmsCommonAction()

    def test_input_filter_context(self):
        alarm_filter = None
        timeout = 60
        alarm_filter_xpath = "alarm_filter_xpath"

        self.alarms_common_action.clear_text_of_enable_element = mock.Mock()

        self.alarms_common_action._input_filter_context(alarm_filter, timeout, alarm_filter_xpath)
        self.alarms_common_action.clear_text_of_enable_element.assert_called_once()

    def test_private_get_alarms_info(self):
        timeout = 1
        key_list = ['a', 'b', 'c']
        value_list = ['value1', 'value2']
        head = 'head'
        alarm_info_xpath = self.alarms_common_action._ALARMS_ROW_XPATH + "[1]//*[text()]"
        elem = mock.Mock()
        expected_list = [{'a': head, 'b': 'value1', 'c': 'value2'}]
        self.alarms_common_action.driver.find_elements_by_xpath = mock.Mock(return_value=[elem])
        self.alarms_common_action.get_attribute_by_xpath = mock.Mock(return_value=head)

        def side_effect(input_xpath, timeout):
            return key_list if input_xpath == self.alarms_common_action._ALARM_COLUMN_HEADER_XPATH else value_list

        self.alarms_common_action.get_fields_info_from_row = mock.Mock(side_effect=side_effect)

        output = self.alarms_common_action._get_alarms_info(timeout)
        self.alarms_common_action.get_fields_info_from_row.assert_has_calls(
            [call.get_fields_info_from_row(self.alarms_common_action._ALARM_COLUMN_HEADER_XPATH, timeout),
             call.get_fields_info_from_row(alarm_info_xpath, timeout)])
        self.alarms_common_action.driver.find_elements_by_xpath.\
            assert_called_once_with(self.alarms_common_action._ALARMS_ROW_XPATH)
        self.alarms_common_action.get_attribute_by_xpath.assert_called_once()
        self.assertEqual(output, expected_list)

    def test_get_alarms_info(self):
        alarm_filter = "111"
        timeout = 1
        save_button_xpath = "save_button_xpath"
        expected_list = [{'a': 1, 'b': 2}]
        self.alarms_common_action._input_filter_context = mock.Mock()
        self.alarms_common_action._get_alarms_info = mock.Mock(return_value=expected_list)

        output = self.alarms_common_action.get_alarms_info(alarm_filter, timeout, save_button_xpath)
        self.alarms_common_action._input_filter_context.assert_called_once_with(alarm_filter,
                                                                                timeout,
                                                                                save_button_xpath)
        self.alarms_common_action._get_alarms_info.assert_called_once_with(timeout)
        self.assertEqual(output, expected_list)

    def test_save_alarms(self):
        save_butto_xpath = "save_alarms"
        timeout = 1

        self.alarms_common_action.click_enabled_element_after_visible = mock.Mock()
        self.alarms_common_action.download_files = mock.Mock()

        self.alarms_common_action.save_alarms(save_butto_xpath, timeout)
        self.alarms_common_action.click_enabled_element_after_visible.assert_called()
        self.alarms_common_action.download_files.assert_called()


